package com.wealthevaluator;

import java.util.List;
import java.util.Map;

public class AccountData {
    public String accountHash;
    public String displayName;
    public boolean isMember;
    public long updatedAt;
    public Map<String, Integer> inventory;
    public Map<String, Integer> equipment;
    public Map<String, Integer> bank;
    public List<OfferData> offers;
    public Map<String, Integer> geCollectionBox;
    public Map<String, Integer> bondPouch;
}

package com.wealthevaluator;

public class OfferData {
    public int slot;
    public int itemId;
    public String itemName;
    public int quantity;
    public int quantityTraded;
    public int price;
    public int spent;
    public boolean isBuy;
    public String state;
}

package com.wealthevaluator;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.text.NumberFormat;
import java.util.*;
import java.util.List;

@Slf4j
class WealthEvaluatorPanel extends PluginPanel
{
	private static final int COINS_ID = 995;
	private static final int TRADEABLE_BOND_ID = 13190;
	private static final int UNTRADEABLE_BOND_ID = 13192;
	private static final NumberFormat NUMBER_FORMAT = NumberFormat.getNumberInstance(Locale.US);

	@Inject
	private ItemManager itemManager;

	@Inject
	private Gson gson;

	@Inject
	private ClientThread clientThread;

	private JComboBox<AccountEntry> accountCombo;
	private JLabel inventoryValue;
	private JLabel equipmentValue;
	private JLabel bankValue;
	private JLabel geOffersValue;
	private JLabel geCollectionValue;
	private JLabel bondPouchValue;
	private JLabel totalValue;

	private List<AccountData> allAccounts = new ArrayList<>();

	// super(false) prevents RuneLite from wrapping this panel in a JScrollPane,
	// which would otherwise show a white viewport background around the content.
	WealthEvaluatorPanel()
	{
		super(false);
	}

	void init()
	{
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		accountCombo = new JComboBox<>();
		accountCombo.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		accountCombo.setForeground(Color.WHITE);
		accountCombo.setFont(FontManager.getRunescapeSmallFont());
		accountCombo.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean isSelected, boolean cellHasFocus)
			{
				JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
				label.setFont(FontManager.getRunescapeSmallFont());
				label.setForeground(Color.WHITE);
				label.setBackground(isSelected ? ColorScheme.MEDIUM_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR);
				return label;
			}
		});
		accountCombo.addActionListener(e -> updateDisplay());

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.setBorder(new EmptyBorder(10, 10, 6, 10));
		header.add(accountCombo, BorderLayout.CENTER);
		add(header, BorderLayout.NORTH);

		// Table inside a darker rounded box
		JPanel tableBox = new JPanel(new BorderLayout());
		tableBox.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		tableBox.setBorder(new EmptyBorder(8, 8, 8, 8));
		tableBox.add(buildTable());

		JPanel tableContainer = new JPanel(new BorderLayout());
		tableContainer.setBackground(ColorScheme.DARK_GRAY_COLOR);
		tableContainer.setBorder(new EmptyBorder(0, 10, 10, 10));
		tableContainer.add(tableBox, BorderLayout.NORTH);
		add(tableContainer, BorderLayout.CENTER);

		List<AccountData> accounts = loadAllAccounts();
		allAccounts = accounts;
		rebuildCombo();
	}

	void deinit()
	{
		removeAll();
	}

	void refresh()
	{
		List<AccountData> loaded = loadAllAccounts();
		SwingUtilities.invokeLater(() ->
		{
			boolean hashesChanged = !accountHashes(loaded).equals(accountHashes(allAccounts));
			allAccounts = loaded;
			if (hashesChanged)
			{
				rebuildCombo();
			}
			else
			{
				updateDisplay();
			}
		});
	}

	private JPanel buildTable()
	{
		JPanel panel = new JPanel(new GridBagLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		String[] rowLabels = {"Inventory", "Worn equipment", "Bank", "GE offers", "GE collection", "Bond pouch"};
		JLabel[] valLabels = new JLabel[rowLabels.length];

		for (int i = 0; i < rowLabels.length; i++)
		{
			JLabel name = new JLabel(rowLabels[i]);
			name.setForeground(Color.WHITE);
			name.setFont(FontManager.getRunescapeSmallFont());

			valLabels[i] = new JLabel("0");
			valLabels[i].setForeground(Color.WHITE);
			valLabels[i].setFont(FontManager.getRunescapeSmallFont());
			valLabels[i].setHorizontalAlignment(SwingConstants.RIGHT);

			panel.add(name, leftConstraint(i));
			panel.add(valLabels[i], rightConstraint(i));
		}

		inventoryValue = valLabels[0];
		equipmentValue = valLabels[1];
		bankValue = valLabels[2];
		geOffersValue = valLabels[3];
		geCollectionValue = valLabels[4];
		bondPouchValue = valLabels[5];

		JSeparator sep = new JSeparator();
		sep.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		sep.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		GridBagConstraints sepC = new GridBagConstraints();
		sepC.gridx = 0;
		sepC.gridy = rowLabels.length;
		sepC.gridwidth = 2;
		sepC.fill = GridBagConstraints.HORIZONTAL;
		sepC.insets = new Insets(5, 0, 5, 0);
		panel.add(sep, sepC);

		int totalRow = rowLabels.length + 1;
		JLabel totalLabel = new JLabel("Total");
		totalLabel.setForeground(Color.WHITE);
		totalLabel.setFont(FontManager.getRunescapeSmallFont());

		totalValue = new JLabel("0");
		totalValue.setForeground(Color.WHITE);
		totalValue.setFont(FontManager.getRunescapeSmallFont());
		totalValue.setHorizontalAlignment(SwingConstants.RIGHT);

		panel.add(totalLabel, leftConstraint(totalRow));
		panel.add(totalValue, rightConstraint(totalRow));

		return panel;
	}

	private static GridBagConstraints leftConstraint(int row)
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = row;
		c.anchor = GridBagConstraints.WEST;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.weightx = 1.0;
		c.insets = new Insets(2, 0, 2, 8);
		return c;
	}

	private static GridBagConstraints rightConstraint(int row)
	{
		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 1;
		c.gridy = row;
		c.anchor = GridBagConstraints.EAST;
		c.insets = new Insets(2, 0, 2, 0);
		return c;
	}

	private void rebuildCombo()
	{
		String selectedHash = accountCombo.getSelectedItem() instanceof AccountEntry
			? ((AccountEntry) accountCombo.getSelectedItem()).hash : null;

		accountCombo.removeAllItems();
		accountCombo.addItem(new AccountEntry(null, "All accounts"));
		for (AccountData acc : allAccounts)
		{
			String name = acc.displayName != null ? acc.displayName : acc.accountHash;
			accountCombo.addItem(new AccountEntry(acc.accountHash, name));
		}

		if (selectedHash != null)
		{
			for (int i = 0; i < accountCombo.getItemCount(); i++)
			{
				if (Objects.equals(accountCombo.getItemAt(i).hash, selectedHash))
				{
					accountCombo.setSelectedIndex(i);
					break;
				}
			}
		}

		updateDisplay();
	}

	// Called on EDT; schedules ItemManager lookups on the client thread,
	// then posts the resulting label strings back to the EDT.
	private void updateDisplay()
	{
		AccountEntry selected = (AccountEntry) accountCombo.getSelectedItem();
		if (selected == null)
		{
			return;
		}

		List<AccountData> toDisplay;
		if (selected.hash == null)
		{
			toDisplay = new ArrayList<>(allAccounts);
		}
		else
		{
			toDisplay = new ArrayList<>();
			for (AccountData acc : allAccounts)
			{
				if (Objects.equals(acc.accountHash, selected.hash))
				{
					toDisplay.add(acc);
					break;
				}
			}
		}

		clientThread.invokeLater(() ->
		{
			long inv = 0, equip = 0, bank = 0, geOffers = 0, geCol = 0, bonds = 0;
			for (AccountData acc : toDisplay)
			{
				inv += computeMapValue(acc.inventory);
				equip += computeMapValue(acc.equipment);
				bank += computeMapValue(acc.bank);
				geOffers += computeOffersValue(acc.offers);
				geCol += computeMapValue(acc.geCollectionBox);
				bonds += computeMapValue(acc.bondPouch);
			}
			final long fInv = inv, fEquip = equip, fBank = bank,
				fGeo = geOffers, fGec = geCol, fBonds = bonds,
				fTotal = inv + equip + bank + geOffers + geCol + bonds;

			SwingUtilities.invokeLater(() ->
			{
				inventoryValue.setText(fmt(fInv));
				equipmentValue.setText(fmt(fEquip));
				bankValue.setText(fmt(fBank));
				geOffersValue.setText(fmt(fGeo));
				geCollectionValue.setText(fmt(fGec));
				bondPouchValue.setText(fmt(fBonds));
				totalValue.setText(fmt(fTotal));
			});
		});
	}

	private long computeMapValue(Map<String, Integer> items)
	{
		if (items == null)
		{
			return 0;
		}
		long total = 0;
		int bondPrice = -1;
		for (Map.Entry<String, Integer> entry : items.entrySet())
		{
			int id;
			try
			{
				id = Integer.parseInt(entry.getKey());
			}
			catch (NumberFormatException e)
			{
				continue;
			}
			int qty = entry.getValue();
			if (qty <= 0)
			{
				continue;
			}

			if (id == COINS_ID)
			{
				total += qty;
			}
			else if (id == UNTRADEABLE_BOND_ID)
			{
				if (bondPrice < 0)
				{
					bondPrice = itemManager.getItemPrice(TRADEABLE_BOND_ID);
				}
				total += (long) ((int) (0.9 * bondPrice)) * qty;
			}
			else
			{
				int price = itemManager.getItemPrice(id);
				if (price > 0)
				{
					total += (long) price * qty;
				}
			}
		}
		return total;
	}

	// Values active offers: remaining coins for BUYING, remaining item GE value for SELLING.
	// BOUGHT/SOLD/CANCELLED offers have their contents in the GE collection box already.
	private long computeOffersValue(List<OfferData> offers)
	{
		if (offers == null)
		{
			return 0;
		}
		long total = 0;
		for (OfferData offer : offers)
		{
			if (offer == null || "EMPTY".equals(offer.state))
			{
				continue;
			}
			if ("BUYING".equals(offer.state))
			{
				long remainingCoins = (long) (offer.quantity - offer.quantityTraded) * offer.price;
				if (remainingCoins > 0)
				{
					total += remainingCoins;
				}
			}
			else if ("SELLING".equals(offer.state))
			{
				int remaining = offer.quantity - offer.quantityTraded;
				if (remaining > 0)
				{
					int price = itemManager.getItemPrice(offer.itemId);
					if (price > 0)
					{
						total += (long) price * remaining;
					}
				}
			}
		}
		return total;
	}

	private List<AccountData> loadAllAccounts()
	{
		List<AccountData> result = new ArrayList<>();
		File dataDir = WealthEvaluatorPlugin.DATA_DIR;
		if (!dataDir.exists())
		{
			return result;
		}
		File[] files = dataDir.listFiles((d, name) -> name.endsWith(".json") && !name.endsWith(".tmp"));
		if (files == null)
		{
			return result;
		}
		for (File f : files)
		{
			try
			{
				String json = new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8);
				AccountData data = gson.fromJson(json, AccountData.class);
				if (data != null)
				{
					result.add(data);
				}
			}
			catch (Exception e)
			{
				log.warn("Failed to read {}", f, e);
			}
		}
		return result;
	}

	private static Set<String> accountHashes(List<AccountData> list)
	{
		Set<String> set = new HashSet<>();
		for (AccountData a : list)
		{
			if (a.accountHash != null)
			{
				set.add(a.accountHash);
			}
		}
		return set;
	}

	private static String fmt(long value)
	{
		return NUMBER_FORMAT.format(value);
	}

	private static class AccountEntry
	{
		final String hash;
		final String name;

		AccountEntry(String hash, String name)
		{
			this.hash = hash;
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}

		@Override
		public boolean equals(Object o)
		{
			return o instanceof AccountEntry && Objects.equals(((AccountEntry) o).hash, hash);
		}

		@Override
		public int hashCode()
		{
			return Objects.hashCode(hash);
		}
	}
}

package com.wealthevaluator;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.RuneLite;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

@Slf4j
@PluginDescriptor(name = "Wealth Evaluator")
public class WealthEvaluatorPlugin extends Plugin
{
	static final File DATA_DIR = new File(RuneLite.RUNELITE_DIR, "wealth-evaluator");

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Gson gson;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private WealthEvaluatorPanel panel;

	// GE collection container IDs per slot (discovered empirically via ItemContainerChanged logging)
	private static final int[] GE_COLLECT_IDS = {518, 519, 520, 521, 522, 523, 539, 540};
	// Bond pouch container ID
	private static final int BOND_POUCH_ID = 536;

	private NavigationButton navButton;

	private boolean dirty = false;
	private Map<String, Integer> savedBank = new HashMap<>();
	private Map<String, Integer> savedGeCollectionBox = new HashMap<>();
	private Map<String, Integer> savedBondPouch = new HashMap<>();

	@Override
	protected void startUp()
	{
		DATA_DIR.mkdirs();

		final BufferedImage icon = ImageUtil.loadImageResource(WealthEvaluatorPlugin.class, "icon.png");
		SwingUtilities.invokeLater(() ->
		{
			try
			{
				panel.init();
			}
			catch (Exception e)
			{
				log.error("Failed to initialise Wealth Evaluator panel", e);
			}
			navButton = NavigationButton.builder()
				.tooltip("Wealth Evaluator")
				.icon(icon)
				.priority(6)
				.panel(panel)
				.build();
			clientToolbar.addNavigation(navButton);
		});

		log.debug("Wealth Evaluator started");
	}

	@Override
	protected void shutDown()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			flush();
		}
		SwingUtilities.invokeLater(() ->
		{
			clientToolbar.removeNavigation(navButton);
			panel.deinit();
		});
		log.debug("Wealth Evaluator stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			loadSavedData();
			dirty = true;
		}
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		dirty = true;
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		if (id == InventoryID.INVENTORY.getId() || id == InventoryID.EQUIPMENT.getId())
		{
			dirty = true;
		}
		else if (id == InventoryID.BANK.getId())
		{
			savedBank = parseContainer(event.getItemContainer());
			dirty = true;
		}
		else if (id == BOND_POUCH_ID)
		{
			savedBondPouch = parseContainer(event.getItemContainer());
			dirty = true;
		}
		else if (isGeCollectId(id))
		{
			updateSavedGeCollectionBox();
			dirty = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (dirty)
		{
			dirty = false;
			flush();
		}
	}

	private void loadSavedData()
	{
		long hash = client.getAccountHash();
		if (hash == -1)
		{
			return;
		}

		File dataFile = new File(DATA_DIR, hash + ".json");
		if (!dataFile.exists())
		{
			return;
		}

		try
		{
			String json = new String(Files.readAllBytes(dataFile.toPath()), StandardCharsets.UTF_8);
			AccountData existing = gson.fromJson(json, AccountData.class);
			if (existing != null)
			{
				if (existing.bank != null) savedBank = existing.bank;
				if (existing.geCollectionBox != null) savedGeCollectionBox = existing.geCollectionBox;
				if (existing.bondPouch != null) savedBondPouch = existing.bondPouch;
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to load existing data for {}", hash, e);
		}
	}

	private void flush()
	{
		long hash = client.getAccountHash();
		if (hash == -1)
		{
			return;
		}

		AccountData data = buildAccountData(hash);
		String json = gson.toJson(data);

		File dataFile = new File(DATA_DIR, hash + ".json");
		File tmp = new File(DATA_DIR, hash + ".json.tmp");

		try
		{
			Files.write(tmp.toPath(), json.getBytes(StandardCharsets.UTF_8));
			Files.move(tmp.toPath(), dataFile.toPath(),
				StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
			panel.refresh();
		}
		catch (IOException e)
		{
			log.warn("Failed to write data for {}", hash, e);
		}
	}

	private AccountData buildAccountData(long hash)
	{
		AccountData data = new AccountData();
		data.accountHash = String.valueOf(hash);
		data.displayName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : null;
		data.isMember = client.getWorldType().contains(WorldType.MEMBERS);
		data.updatedAt = System.currentTimeMillis();

		data.inventory = parseContainer(client.getItemContainer(InventoryID.INVENTORY));
		data.equipment = parseContainer(client.getItemContainer(InventoryID.EQUIPMENT));
		data.bank = new HashMap<>(savedBank);
		data.geCollectionBox = new HashMap<>(savedGeCollectionBox);
		data.bondPouch = new HashMap<>(savedBondPouch);

		data.offers = new ArrayList<>();
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers != null)
		{
			for (int i = 0; i < offers.length; i++)
			{
				data.offers.add(buildOfferData(i, offers[i]));
			}
		}

		return data;
	}

	private OfferData buildOfferData(int slot, GrandExchangeOffer offer)
	{
		OfferData od = new OfferData();
		od.slot = slot;
		if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY)
		{
			od.state = "EMPTY";
			return od;
		}
		od.itemId = offer.getItemId();
		od.quantity = offer.getTotalQuantity();
		od.quantityTraded = offer.getQuantitySold();
		od.price = offer.getPrice();
		od.spent = offer.getSpent();
		od.state = offer.getState().name();
		od.isBuy = od.state.contains("BUY");
		try
		{
			od.itemName = itemManager.getItemComposition(offer.getItemId()).getName();
		}
		catch (Exception e)
		{
			od.itemName = "";
		}
		return od;
	}

	private static boolean isGeCollectId(int id)
	{
		for (int collectId : GE_COLLECT_IDS)
		{
			if (id == collectId) return true;
		}
		return false;
	}

	private void updateSavedGeCollectionBox()
	{
		Map<String, Integer> combined = new HashMap<>();
		for (int id : GE_COLLECT_IDS)
		{
			parseContainer(client.getItemContainer(id)).forEach((k, v) -> combined.merge(k, v, Integer::sum));
		}
		savedGeCollectionBox = combined;
	}

	private Map<String, Integer> parseContainer(ItemContainer container)
	{
		Map<String, Integer> result = new HashMap<>();
		if (container == null)
		{
			return result;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() == -1 || item.getQuantity() <= 0)
			{
				continue;
			}
			if (itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId() > 0)
			{
				continue;
			}
			int id = itemManager.canonicalize(item.getId());
			String key = String.valueOf(id);
			result.merge(key, item.getQuantity(), Integer::sum);
		}
		return result;
	}

}

package com.wealthevaluator;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class WealthEvaluatorPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(WealthEvaluatorPlugin.class);
		RuneLite.main(args);
	}
}
